import Foundation
import CryptoKit

// CI/CD Pipeline Build Artifact Manager with Audit Logging
// Handles temporary storage of build artifacts during pipeline execution

struct AuditEntry: Codable {
    let timestamp: Date
    let action: String
    let actor: String
    let resourcePath: String
    let checksum: String
}

class PipelineArtifactManager {
    private let baseDirectory: String
    private let auditLogPath: String
    private let pipelineId: String
    private var auditEntries: [AuditEntry] = []

    private let fileManager = FileManager.default

    init(pipelineId: String, workspaceRoot: String) {
        self.pipelineId = pipelineId
        self.baseDirectory = workspaceRoot
        self.auditLogPath = "\(workspaceRoot)/audit/\(pipelineId).json"
    }

    /// Creates a secure temporary directory for build stage artifacts
    func createStagingArea(forStage stage: String, actor: String) throws -> String {
        let stagingPath = computeStagingPath(stage: stage)

        // Ensure parent directories exist
        try fileManager.createDirectory(
            atPath: stagingPath,
            withIntermediateDirectories: true,
            attributes: [.posixPermissions: 0o700]
        )

        try logAuditEvent(action: "create_staging", actor: actor, resourcePath: stagingPath)
        return stagingPath
    }

    /// Stores a build artifact in the staging area with integrity verification
    func storeArtifact(data: Data, name: String, stage: String, actor: String) throws -> String {
        let stagingPath = computeStagingPath(stage: stage)
        let safeName = try sanitizeArtifactName(name)
        let artifactPath = "\(stagingPath)/\(safeName)"

        // Compute checksum for integrity
        let checksum = computeChecksum(data: data)

        // Write artifact to temporary location first, then move
        let tempPath = createTempFile(inDirectory: stagingPath, prefix: "artifact_")

        try data.write(to: URL(fileURLWithPath: tempPath))

        // Set restrictive permissions on the temp file
        try fileManager.setAttributes(
            [.posixPermissions: 0o600],
            ofItemAtPath: tempPath
        )

        // Atomic move to final location
        if fileManager.fileExists(atPath: artifactPath) {
            try fileManager.removeItem(atPath: artifactPath)
        }
        try fileManager.moveItem(atPath: tempPath, toPath: artifactPath)

        try logAuditEvent(action: "store_artifact", actor: actor, resourcePath: artifactPath, checksum: checksum)
        return artifactPath
    }

    /// Retrieves artifact with integrity check
    func retrieveArtifact(name: String, stage: String, expectedChecksum: String?, actor: String) throws -> Data {
        let stagingPath = computeStagingPath(stage: stage)
        let safeName = try sanitizeArtifactName(name)
        let artifactPath = "\(stagingPath)/\(safeName)"

        guard fileManager.fileExists(atPath: artifactPath) else {
            throw PipelineError.artifactNotFound(name)
        }

        let data = try Data(contentsOf: URL(fileURLWithPath: artifactPath))

        if let expected = expectedChecksum {
            let actual = computeChecksum(data: data)
            guard actual == expected else {
                throw PipelineError.integrityCheckFailed(expected: expected, actual: actual)
            }
        }

        try logAuditEvent(action: "retrieve_artifact", actor: actor, resourcePath: artifactPath)
        return data
    }

    /// Cleanup staging area after pipeline completion
    func cleanupStagingArea(stage: String, actor: String) throws {
        let stagingPath = computeStagingPath(stage: stage)

        if fileManager.fileExists(atPath: stagingPath) {
            try fileManager.removeItem(atPath: stagingPath)
        }

        try logAuditEvent(action: "cleanup_staging", actor: actor, resourcePath: stagingPath)
    }

    // MARK: - Private Methods

    private func computeStagingPath(stage: String) -> String {
        let sanitizedStage = stage.replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "..", with: "_")
        return "\(baseDirectory)/staging/\(pipelineId)/\(sanitizedStage)"
    }

    /// Validates and sanitizes an artifact file name to prevent path traversal.
    /// The name must be a simple, non-empty file name with no path separators
    /// or parent-directory references.
    private func sanitizeArtifactName(_ name: String) throws -> String {
        // Reject empty names and reserved directory entries
        guard !name.isEmpty, name != ".", name != ".." else {
            throw PipelineError.invalidArtifactName(name)
        }
        // Reject any path separators or parent-directory traversal sequences
        guard !name.contains("/"),
              !name.contains("\\"),
              !name.contains(".."),
              !name.hasPrefix(".") else {
            throw PipelineError.invalidArtifactName(name)
        }
        // Ensure the resolved last path component matches the input exactly,
        // guarding against any residual normalization surprises.
        let lastComponent = (name as NSString).lastPathComponent
        guard lastComponent == name else {
            throw PipelineError.invalidArtifactName(name)
        }
        return name
    }

    /// Creates a temporary file using cryptographically secure random bytes
    private func createTempFile(inDirectory directory: String, prefix: String) -> String {
        var randomBytes = [UInt8](repeating: 0, count: 32)
        let status = SecRandomCopyBytes(kSecRandomDefault, randomBytes.count, &randomBytes)
        precondition(status == errSecSuccess, "Failed to generate secure random bytes")

        let randomHex = randomBytes.map { String(format: "%02x", $0) }.joined()
        let filename = "\(prefix)\(randomHex)"
        return "\(directory)/\(filename)"
    }

    private func computeChecksum(data: Data) -> String {
        let digest = SHA256.hash(data: data)
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    private func logAuditEvent(action: String, actor: String, resourcePath: String, checksum: String = "") throws {
        let entry = AuditEntry(
            timestamp: Date(),
            action: action,
            actor: actor,
            resourcePath: resourcePath,
            checksum: checksum
        )
        auditEntries.append(entry)

        // Write audit log atomically
        let auditDir = (auditLogPath as NSString).deletingLastPathComponent
        try fileManager.createDirectory(
            atPath: auditDir,
            withIntermediateDirectories: true,
            attributes: [.posixPermissions: 0o700]
        )

        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = .prettyPrinted
        let jsonData = try encoder.encode(auditEntries)

        // Write audit log to temp file then rename for atomicity
        let auditTempPath = createTempFile(inDirectory: auditDir, prefix: "audit_")
        try jsonData.write(to: URL(fileURLWithPath: auditTempPath))
        try fileManager.setAttributes([.posixPermissions: 0o600], ofItemAtPath: auditTempPath)

        if fileManager.fileExists(atPath: auditLogPath) {
            try fileManager.removeItem(atPath: auditLogPath)
        }
        try fileManager.moveItem(atPath: auditTempPath, toPath: auditLogPath)
    }
}

enum PipelineError: Error {
    case artifactNotFound(String)
    case integrityCheckFailed(expected: String, actual: String)
    case unauthorized(String)
    case invalidArtifactName(String)
}

// MARK: - Pipeline Execution Context

class PipelineExecutor {
    private let artifactManager: PipelineArtifactManager
    private let authorizedActors: Set<String>

    init(pipelineId: String, workspaceRoot: String, authorizedActors: Set<String>) {
        self.artifactManager = PipelineArtifactManager(
            pipelineId: pipelineId,
            workspaceRoot: workspaceRoot
        )
        self.authorizedActors = authorizedActors
    }

    func executeStage(name: String, actor: String, buildAction: (String) throws -> [(String, Data)]) throws {
        guard authorizedActors.contains(actor) else {
            throw PipelineError.unauthorized(actor)
        }

        let stagingPath = try artifactManager.createStagingArea(forStage: name, actor: actor)

        let artifacts = try buildAction(stagingPath)

        for (artifactName, artifactData) in artifacts {
            _ = try artifactManager.storeArtifact(
                data: artifactData,
                name: artifactName,
                stage: name,
                actor: actor
            )
        }
    }
}
